ImFont* gUi = nullptr;
ImFont* gLegend = nullptr;
ImFont* gReading = nullptr;

// The fallback, in one place. ImGui::GetFont() is the face currently bound,
// which on the failure path is its own built-in bitmap one - wrong, legible,
// and never null.
ImFont* orCurrent(ImFont* f) { return f != nullptr ? f : ImGui::GetFont(); }

bool gSystemSerif = false;

// --- font files from the operating system -----------------------------------
//
// Georgia (0.84.0) and the CJK faces are read from where the system keeps
// them and never shipped: Georgia is Microsoft's typeface, licensed with
// Windows for use on that machine, and the redistribution the embedded OFL
// faces permit is exactly what its licence does not; the CJK faces are that
// AND tens of megabytes each (core/scripts.hpp).
//
// PINNED FILES STAY IN MEMORY FOR THE LIFE OF THE PROCESS. The atlas is given
// their bytes with FontDataOwnedByAtlas = false, and Chain hands pointers into
// them to its callers, so a pinned file is never freed. A file is pinned only
// when a face in it is actually put in a chain.
//
// KEPT FILES (0.99.74) ARE THE ONES ASKING FOUND USABLE, UNTIL THE NAMES ARE
// IN THE ATLAS. Asking whether a language can be drawn reads the candidate
// files in order until one has the characters. A candidate that does not is let
// go at once. The one that does is KEPT, because the question is nearly always
// asked in order to put that face in a chain, and reading a 14 to 21 MB file a
// second time to hand the atlas the bytes the scan has just looked at was half
// of the cost that froze the language list (field hangs CE8EBCD986C97CEB and
// D28A155E1A128889). pin() takes a kept file's bytes instead of reading it.
//
// Once applyPending() has merged the names' faces it lets go every kept file the
// names did not pin (gKept.clear()): the list shows Traditional Chinese and
// Japanese names with YaHei, so JhengHei and Yu Gothic were only looked at, and
// holding their 35 MB for the life of the process would be a footprint the old
// code never had. The price is one more read: a language chosen afterwards whose
// file was let go (Japanese, here) reads it again when its face is put in a chain,
// once, in one bulk read, on the GUI thread.
//
// THE READ ITSELF is one read() into a buffer sized from the file, not an
// istreambuf_iterator walk - which is a virtual call per BYTE plus the vector's
// regrowth, and was the stack of the 0.99.70 hang. readFileUncached() touches
// no cache and no global of the GUI thread, so the scan's worker thread can use
// it.
using Bytes = std::shared_ptr<const std::vector<unsigned char>>;
std::map<std::string, Bytes> gPinned;
std::map<std::string, Bytes> gKept;

// Test seams (fonts.hpp): a delay inside every read, and a count of opens per
// path. Both are touched by the scan worker as well as the GUI thread.
std::atomic<unsigned> gReadDelayMs{0};
std::mutex gReadCountsMutex;
std::map<std::string, int> gReadCounts;

Bytes readFileUncached(const std::string& path) {
    if (path.empty()) { return nullptr; }
    std::error_code ec;
    if (!std::filesystem::is_regular_file(path, ec)) { return nullptr; }
    if (const unsigned ms = gReadDelayMs.load(); ms != 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(ms));
    }
    std::ifstream f(path, std::ios::binary);
    if (!f) { return nullptr; }
    {
        const std::lock_guard<std::mutex> lock(gReadCountsMutex);
        ++gReadCounts[path];
    }
    f.seekg(0, std::ios::end);
    const std::streamoff size = f.tellg();
    if (size <= 0) { return nullptr; }  // empty, or the size could not be read
    f.seekg(0, std::ios::beg);
    auto bytes = std::make_shared<std::vector<unsigned char>>(static_cast<std::size_t>(size));
    f.read(reinterpret_cast<char*>(bytes->data()), size);
    if (f.gcount() != size) { return nullptr; }  // a short read is not a font
    return bytes;
}

// The GUI thread's reader: what is pinned, then what the scan kept, then the disk.
Bytes readFile(const std::string& path) {
    if (path.empty()) { return nullptr; }
    if (const auto it = gPinned.find(path); it != gPinned.end()) { return it->second; }
    if (const auto it = gKept.find(path); it != gKept.end()) { return it->second; }
    return readFileUncached(path);
}

// Remember a file asking found usable (unless it is already pinned).
void keep(const std::string& path, const Bytes& bytes) {
    if (bytes != nullptr && gPinned.count(path) == 0) { gKept.emplace(path, bytes); }
}

Bytes pin(const std::string& path) {
    Bytes b = readFile(path);
    if (b != nullptr) {
        gPinned.emplace(path, b);
        gKept.erase(path);
    }
    return b;
}

ChainFace embedded(const char* label, const unsigned char* data, unsigned int len) {
    return ChainFace{label, data, len, 0};
}

// The Georgia pair, when this machine has both files. Read once.
bool gGeorgiaTried = false;
ChainFace gGeorgia;
ChainFace gGeorgiaBold;

bool haveGeorgia() {
    if (!gGeorgiaTried) {
        gGeorgiaTried = true;
        const Bytes r = pin(systemFontPath("georgia.ttf"));
        const Bytes b = r != nullptr ? pin(systemFontPath("georgiab.ttf")) : nullptr;
        if (r != nullptr && b != nullptr) {
            gGeorgia = ChainFace{"Georgia", r->data(), r->size(), 0};
            gGeorgiaBold = ChainFace{"Georgia Bold", b->data(), b->size(), 0};
        }
    }
    return gGeorgia.data != nullptr;
}

// --- the system CJK faces -----------------------------------------------------
//
// For each CJK standard, the usable faces this machine has, found lazily and
// in core/scripts.hpp's order of preference: a candidate is usable when its
// file exists and a face in it has every probe character. Usually only the
// first is ever looked for; a second is sought only when a catalogue uses a
// character the first lacks (Yu Gothic has no 简, say).
struct CjkPick {
    std::string path;
    std::string label;  // "msyh.ttc#1"
    int index = 0;
};
struct CjkScan {
    std::vector<scripts::SystemFace> candidates;
    std::size_t next = 0;
    bool started = false;
    std::vector<CjkPick> found;
};
std::map<int, CjkScan> gScans;

// --- the system-font scan, off the GUI thread (0.99.74) -------------------------
//
// The first usable candidate of EACH standard, found by one worker thread so the
// language list never reads a 20 MB font inside a frame (fonts.hpp has the
// story and the trade). The worker walks exactly the candidates usableCjk()
// would, in the same order, with the same probe; it differs in three ways only:
// it keeps no more than the first usable face of a standard, it never reads a
// file twice (a path two standards share is read once), and it runs somewhere
// else.
//
// WHAT THE WORKER MAY TOUCH. Its own arguments and the file system: no ImGui,
// no i18n, and none of this file's GUI-thread globals (gScans, gPinned, gKept).
// The GUI thread prepares everything it needs before starting it - the
// candidates, their resolved paths (the environment is read here, not there),
// the probe characters, and the bytes already in memory - and adopts the answer
// in publishScan(). The only shared state is the small block below, behind one
// mutex.
enum class ScanState { NotStarted, Running, Done };

struct ScanJob {                   // one standard
    int face = 0;                  // a scripts::CjkFace
    CjkScan scan;                  // started, with its candidates; the worker fills next and found
    std::vector<std::string> paths;  // each candidate's resolved path
    std::vector<unsigned int> probe;
};
struct ScanOutcome {
    std::map<int, CjkScan> scans;           // the standards the worker finished, each decided for k = 0
    std::map<std::string, Bytes> bytes;     // the bytes of each usable first candidate
};

std::mutex gScanMutex;
std::condition_variable gScanCv;
ScanState gScanState = ScanState::NotStarted;  // guarded by gScanMutex
ScanOutcome gScanOutcome;                      // guarded by gScanMutex; written once, by the worker
std::atomic<bool> gScanCancel{false};          // shutdown(): finish the file in hand and stop
std::thread gScanThread;                       // GUI thread only (start, join)
bool gScanPublished = false;                   // GUI thread only

bool scanRunning() {
    const std::lock_guard<std::mutex> lock(gScanMutex);
    return gScanState == ScanState::Running;
}
bool scanDone() {
    const std::lock_guard<std::mutex> lock(gScanMutex);
    return gScanState == ScanState::Done;
}

// Safe to call from a thread other than the GUI's: see "what the worker may touch".
ScanOutcome scanStandards(std::vector<ScanJob>& jobs, std::map<std::string, Bytes>& have) {
    ScanOutcome out;
    for (ScanJob& job : jobs) {
        CjkScan& s = job.scan;
        while (s.found.empty() && s.next < s.candidates.size()) {
            if (gScanCancel.load()) { return out; }
            const std::size_t i = s.next++;
            const std::string& path = job.paths[i];
            Bytes b;
            if (const auto it = have.find(path); it != have.end()) {
                b = it->second;
            } else {
                b = readFileUncached(path);
                if (b != nullptr) { have.emplace(path, b); }
            }
            if (b == nullptr) { continue; }
            const int index = fontprobe::pickFace(b->data(), b->size(), s.candidates[i].nameHint, job.probe);
            if (index < 0) { continue; }
            const std::string file = std::filesystem::path(path).filename().string();
            s.found.push_back(CjkPick{path, file + "#" + std::to_string(index), index});
            out.bytes.emplace(path, b);
        }
        out.scans.emplace(job.face, std::move(s));  // decided for k = 0: a pick, or every candidate tried
    }
    return out;
}

void scanWorker(std::vector<ScanJob> jobs, std::map<std::string, Bytes> have) {
    ScanOutcome out;
    try {
        out = scanStandards(jobs, have);
    } catch (...) {
        // Out of memory, say: the standards finished before it stand, and the
        // rest are answered on demand, as they were before the scan existed.
        out = ScanOutcome();
    }
    // The worker's own references go before it announces it is done.
    jobs.clear();
    have.clear();
    {
        const std::lock_guard<std::mutex> lock(gScanMutex);
        gScanOutcome = std::move(out);
        gScanState = ScanState::Done;
    }
    gScanCv.notify_all();
}

// Starts the scan, once. GUI thread only. A standard the GUI thread has already
// decided on demand is left out - its files have been read.
void startSystemFontScan() {
    {
        const std::lock_guard<std::mutex> lock(gScanMutex);
        if (gScanState != ScanState::NotStarted) { return; }
        gScanState = ScanState::Running;
    }
    std::vector<ScanJob> jobs;
    for (const scripts::CjkFace face : scripts::kCjkFaces) {
        if (const auto it = gScans.find(static_cast<int>(face)); it != gScans.end() && it->second.started) {
            continue;
        }
        ScanJob job;
        job.face = static_cast<int>(face);
        job.scan.started = true;
        job.scan.candidates = scripts::systemCandidates(face, kWindows);
        for (const scripts::SystemFace& c : job.scan.candidates) {
            job.paths.push_back(kWindows ? systemFontPath(c.path.c_str()) : c.path);
        }
        job.probe = scripts::probeCodePoints(face);
        jobs.push_back(std::move(job));
    }
    // What is already in memory is not read again.
    std::map<std::string, Bytes> have = gPinned;
    have.insert(gKept.begin(), gKept.end());
    gScanCancel.store(false);
    try {
        gScanThread = std::thread(scanWorker, std::move(jobs), std::move(have));
    } catch (...) {
        // No thread to be had: every standard is answered on demand, as it was.
        {
            const std::lock_guard<std::mutex> lock(gScanMutex);
            gScanOutcome = ScanOutcome();
            gScanState = ScanState::Done;
        }
        gScanCv.notify_all();
    }
}

// Adopts a finished scan's answers into gScans and gKept, and joins the worker
// (it has set Done and is leaving). GUI thread only; cheap when there is nothing to do.
void publishScan() {
    if (gScanPublished) { return; }
    ScanOutcome out;
    {
        const std::lock_guard<std::mutex> lock(gScanMutex);
        if (gScanState != ScanState::Done) { return; }
        out = std::move(gScanOutcome);
        gScanOutcome = ScanOutcome();
    }
    gScanPublished = true;
    if (gScanThread.joinable()) { gScanThread.join(); }
    for (auto& [face, scan] : out.scans) {
        CjkScan& mine = gScans[face];
        if (mine.started) { continue; }  // decided on demand while the worker ran: that stands
        mine = std::move(scan);
        for (const CjkPick& p : mine.found) {
            if (const auto b = out.bytes.find(p.path); b != out.bytes.end()) { keep(p.path, b->second); }
        }
    }
}

// The first usable face of `face` (k = 0), or the k-th when asked: the EXACT
// answer. Waits for a scan that is deciding this standard rather than reading
// its files again beside it; with no scan started it walks the candidates itself,
// on the calling thread, as it always did.
const CjkPick* usableCjk(scripts::CjkFace face, std::size_t k) {
    publishScan();
    CjkScan& s = gScans[static_cast<int>(face)];
    if (!s.started && scanRunning()) { waitForSystemFontScan(); }  // which publishes
    if (!s.started) {
        s.started = true;
        s.candidates = scripts::systemCandidates(face, kWindows);
    }
    while (s.found.size() <= k && s.next < s.candidates.size()) {
        const scripts::SystemFace& c = s.candidates[s.next++];
        const std::string path = kWindows ? systemFontPath(c.path.c_str()) : c.path;
        const Bytes b = readFile(path);
        if (b == nullptr) { continue; }
        const int index = fontprobe::pickFace(b->data(), b->size(), c.nameHint,
                                              scripts::probeCodePoints(face));
        if (index < 0) { continue; }
        keep(path, b);  // usable: pin() will want these bytes, not another read
        const std::string file = std::filesystem::path(path).filename().string();
        s.found.push_back(CjkPick{path, file + "#" + std::to_string(index), index});
    }
    return k < s.found.size() ? &s.found[k] : nullptr;
}

// A static backstop: whatever path the process leaves by, a worker still
// reading is joined, never destroyed joinable (which is std::terminate). Defined
// after the thread and the mutex it uses, so it is destroyed before them.
// Application teardown calls shutdown() itself, earlier, before ImGui goes.
struct ScanJoiner {
    ~ScanJoiner() { shutdown(); }
} gScanJoiner;

ChainFace pinCjk(const CjkPick& p) {
    const Bytes b = pin(p.path);
    if (b == nullptr) { return {}; }
    return ChainFace{p.label, b->data(), b->size(), p.index};
}

bool sameFace(const ChainFace& a, const ChainFace& b) {
    return a.data == b.data && a.index == b.index;
}

// The CJK faces a set of code points needs from standard `face`: the first
// usable one, then - only while some of `need` is still missing - the next,
// up to three. None when the machine has no usable face at all.
std::vector<ChainFace> cjkFacesFor(scripts::CjkFace face, const std::vector<unsigned int>& need) {
    std::vector<ChainFace> out;
    if (face == scripts::CjkFace::None) { return out; }
    std::vector<unsigned int> left = need;
    for (std::size_t k = 0; k < 3; ++k) {
        const CjkPick* p = usableCjk(face, k);
        if (p == nullptr) { break; }
        const ChainFace f = pinCjk(*p);
        if (f.data == nullptr) { continue; }
        const std::size_t before = left.size();
        const fontprobe::Face probe{f.data, f.len, f.index};
        left.erase(std::remove_if(left.begin(), left.end(),
                                  [&](unsigned int cp) { return fontprobe::has(probe, cp); }),
                   left.end());
        // The first is always taken - it is THE face for this standard; a
        // later one only for what it adds.
        if (k == 0 || left.size() < before) { out.push_back(f); }
        if (left.empty()) { break; }
    }
    return out;
}

// --- what the atlas holds now -------------------------------------------------

std::string gPair;
// The planned chain of each role as it stands in the atlas, and - behind the
// UI chain only - the faces added so the language list can draw names.
std::vector<ChainFace> gChainUi, gChainLegend, gChainReading;
std::vector<ChainFace> gNamesUi;
std::string gWantLanguage = "en";
bool gWantNames = false;
bool gNamesDone = false;  // names faces added for the chain in force
bool gDirty = false;
// The pair the interface THEME asks for first (setPreferredPair); empty is the
// application's own order - Georgia, then Saira, then Noto.
std::string gPreferPair;

// The em every face in a role is drawn at: its REFERENCE face's, the one
// English is lettered in here (fonts.hpp says why).
float emScale(const ChainFace& face, const ChainFace& ref) {
    if (sameFace(face, ref)) { return 1.0f; }
    const float a = fontprobe::emSpan({face.data, face.len, face.index});
    const float b = fontprobe::emSpan({ref.data, ref.len, ref.index});
    return (a > 0.0f && b > 0.0f) ? a / b : 1.0f;
}

ChainFace uiReference() {
    return haveGeorgia() ? gGeorgia
                         : embedded("Saira Condensed Medium", fontdata::kFontUiTtf, fontdata::kFontUiTtfLen);
}
ChainFace legendReference() {
    return haveGeorgia() ? gGeorgiaBold
                         : embedded("Saira Condensed SemiBold", fontdata::kFontLegendTtf,
                                    fontdata::kFontLegendTtfLen);
}
ChainFace readingReference() {
    return embedded("Nova Mono", fontdata::kFontReadingTtf, fontdata::kFontReadingTtfLen);
}

// One role's chain into the atlas, as ONE ImFont: the first face at the
// role's size, every later one merged into it.
//
// FontDataOwnedByAtlas = false on every source, and it is not optional: the
// embedded bytes are a constexpr array in read-only storage and the system
// files are pinned for the life of the process. ImGui's default is to take
// ownership and free() the pointer when the atlas is destroyed, which on this
// data is a heap corruption at shutdown - and shutdown is exactly where nobody
// looks for one. The const_cast is for AddFontFromMemoryTTF's non-const
// parameter, which exists for that ownership case; neither rasteriser ImGui
// ships writes to font data.
ImFont* addChain(const std::vector<ChainFace>& faces, float size, const ChainFace& ref,
                 const char* role, std::vector<ChainFace>& added) {
    ImFontAtlas* atlas = ImGui::GetIO().Fonts;
    ImFont* font = nullptr;
    added.clear();
    for (std::size_t i = 0; i < faces.size(); ++i) {
        const ChainFace& f = faces[i];
        if (f.data == nullptr) { continue; }
        ImFontConfig cfg;
        cfg.FontDataOwnedByAtlas = false;
        cfg.FontNo = static_cast<ImU32>(f.index);
        cfg.ExtraSizeScale = emScale(f, ref);
        // Shows up in the Metrics/Debug window, so a font problem can be
        // diagnosed by looking rather than by guessing which face is wrong.
        std::snprintf(cfg.Name, sizeof(cfg.Name), "%s: %s", role, f.label.c_str());
        if (font != nullptr) {
            cfg.MergeMode = true;
            cfg.DstFont = font;
        }
        // A missing or unreadable source is survivable here - the chain simply
        // lacks it - so ImGui is asked not to assert on it.
        cfg.Flags |= ImFontFlags_NoLoadError;
        ImFont* got = atlas->AddFontFromMemoryTTF(const_cast<unsigned char*>(f.data),
                                                  static_cast<int>(f.len), font == nullptr ? size : 0.0f,
                                                  &cfg);
        if (got == nullptr) { continue; }
        font = got;
        added.push_back(f);
    }
    return font;
}

// Merges `faces` behind an existing role font.
void extendChain(ImFont* font, const std::vector<ChainFace>& faces, const ChainFace& ref,
                 const char* role, std::vector<ChainFace>& added) {
    if (font == nullptr) { return; }
    for (const ChainFace& f : faces) {
        ImFontConfig cfg;
        cfg.FontDataOwnedByAtlas = false;
        cfg.FontNo = static_cast<ImU32>(f.index);
        cfg.ExtraSizeScale = emScale(f, ref);
        cfg.MergeMode = true;
        cfg.DstFont = font;
        cfg.Flags |= ImFontFlags_NoLoadError;
        std::snprintf(cfg.Name, sizeof(cfg.Name), "%s: %s", role, f.label.c_str());
        if (ImGui::GetIO().Fonts->AddFontFromMemoryTTF(const_cast<unsigned char*>(f.data),
                                                      static_cast<int>(f.len), 0.0f, &cfg) != nullptr) {
            added.push_back(f);
        }
    }
}

bool startsWith(const std::vector<ChainFace>& whole, const std::vector<ChainFace>& prefix) {
    if (prefix.size() > whole.size()) { return false; }
    for (std::size_t i = 0; i < prefix.size(); ++i) {
        if (!sameFace(whole[i], prefix[i])) { return false; }
    }
    return true;
}

std::vector<ChainFace> tail(const std::vector<ChainFace>& whole, std::size_t from) {
    return std::vector<ChainFace>(whole.begin() + static_cast<std::ptrdiff_t>(from), whole.end());
}

// The whole atlas, from nothing: the three role chains, the UI face made
// ImGui's default. Returns false (and leaves ImGui's own font) when a role's
// first face could not be added.
bool rebuild(const Chain& c) {
    ImGuiIO& io = ImGui::GetIO();
    io.Fonts->ClearFonts();
    gNamesUi.clear();
    gNamesDone = false;
    // ORDER MATTERS ONLY IN ONE RESPECT: the first face added becomes ImGui's
    // default, so the UI face goes first and everything that never pushes a
    // font gets the right one for free.
    gUi = addChain(c.ui, kUiSize, uiReference(), "UI", gChainUi);
    gLegend = addChain(c.legend, kLegendSize, legendReference(), "Legend", gChainLegend);
    gReading = addChain(c.reading, kReadingSize, readingReference(), "Reading", gChainReading);
    if (gUi == nullptr || gLegend == nullptr || gReading == nullptr) {
        // Put the atlas back to a state that can definitely draw. A half-loaded
        // atlas is worse than none: it renders some strings and silently drops
        // others depending on which face a call site happened to push.
        io.Fonts->ClearFonts();
        gUi = gLegend = gReading = nullptr;
        gChainUi.clear();
        gChainLegend.clear();
        gChainReading.clear();
        gPair.clear();
        io.Fonts->AddFontDefault();
        return false;
    }
    gPair = c.pair;
    // The style's base size has to agree with the face just made default, or
    // every height derived from GetTextLineHeight is computed against a size
    // nothing is actually drawn at.
    ImGui::GetStyle().FontSizeBase = kUiSize;
    io.FontDefault = gUi;
    return true;
}

// THE LANGUAGE LIST'S NAMES. Each language is listed by its own name -
// "日本語", "한국어" - which the chain in force (English, say) cannot draw.
// For every language this machine CAN draw whose name still has a character
// nothing in the UI chain has, its standard's own face is merged in behind
// the chain; checked again after each addition, so one YaHei that already
// draws "简体中文", "繁體中文" and "日本語" is the only Chinese face added.
// Returns true when anything was.
bool addNamesFaces() {
    bool added = false;
    for (const cascade::i18n::Language& l : cascade::i18n::languages()) {
        std::vector<unsigned int> cps;
        for (std::size_t i = 0; i < l.name.size();) {
            const unsigned int cp = cascade::core::utf8Decode(l.name, i);
            if (scripts::isCjk(cp)) { cps.push_back(cp); }
        }
        if (cps.empty()) { continue; }
        const scripts::CjkFace face = scripts::cjkFaceFor(l.code, cps);
        if (face == scripts::CjkFace::None || !canDraw(l.code)) { continue; }
        auto drawn = [&](unsigned int cp) {
            for (const auto* chain : {&gChainUi, &gNamesUi}) {
                for (const ChainFace& f : *chain) {
                    if (fontprobe::has({f.data, f.len, f.index}, cp)) { return true; }
                }
            }
            return false;
        };
        if (std::all_of(cps.begin(), cps.end(), drawn)) { continue; }
        const std::vector<ChainFace> sys = cjkFacesFor(face, cps);
        if (sys.empty()) { continue; }
        extendChain(gUi, {sys.front()}, uiReference(), "UI names", gNamesUi);
        added = true;
    }
    return added;
}

