Chain planChain(const std::string& languageCode) {
    Chain c;
    const std::vector<unsigned int> cps = cascade::i18n::codePoints(languageCode);
    std::vector<unsigned int> letters;  // what the PAIR must have
    std::vector<unsigned int> cjk;      // what the system CJK face must have
    for (const unsigned int cp : cps) {
        if (scripts::isCjk(cp)) {
            cjk.push_back(cp);
        } else if (scripts::isLetter(cp)) {
            letters.push_back(cp);
        }
    }

    const ChainFace notoUi = embedded("Noto Sans Condensed Medium", fontdata::kFontFallbackUiTtf,
                                      fontdata::kFontFallbackUiTtfLen);
    const ChainFace notoLegend = embedded("Noto Sans Condensed SemiBold",
                                          fontdata::kFontFallbackLegendTtf,
                                          fontdata::kFontFallbackLegendTtfLen);
    struct Pair {
        const char* name;
        ChainFace ui, legend;
    };
    std::vector<Pair> pairs;
    if (haveGeorgia()) { pairs.push_back({"Georgia", gGeorgia, gGeorgiaBold}); }
    pairs.push_back({"Saira Condensed",
                     embedded("Saira Condensed Medium", fontdata::kFontUiTtf, fontdata::kFontUiTtfLen),
                     embedded("Saira Condensed SemiBold", fontdata::kFontLegendTtf,
                              fontdata::kFontLegendTtfLen)});
    pairs.push_back({"Noto Sans Condensed", notoUi, notoLegend});
    // THE THEME'S PAIR GOES FIRST when it names one (gui/theme.hpp,
    // preferredFontPair) - and still only wins if it has every letter the
    // catalogue needs, so a theme can never cost a language its glyphs.
    if (!gPreferPair.empty()) {
        std::stable_partition(pairs.begin(), pairs.end(),
                              [](const Pair& q) { return gPreferPair == q.name; });
    }

    // THE FIRST PAIR WITH EVERY LETTER. When none has them all (a stray
    // character nothing embedded draws), the one missing fewest, earliest on
    // a tie - so a single odd letter never costs a language its usual face.
    std::size_t best = 0;
    std::size_t bestMissing = static_cast<std::size_t>(-1);
    for (std::size_t i = 0; i < pairs.size(); ++i) {
        const std::size_t m =
            fontprobe::missing({pairs[i].ui.data, pairs[i].ui.len, 0}, letters) +
            fontprobe::missing({pairs[i].legend.data, pairs[i].legend.len, 0}, letters);
        if (m < bestMissing) {
            best = i;
            bestMissing = m;
        }
        if (m == 0) { break; }
    }
    const Pair& p = pairs[best];
    c.pair = p.name;
    const bool isNoto = sameFace(p.ui, notoUi);
    c.ui = {p.ui};
    c.legend = {p.legend};
    if (!isNoto) {
        c.ui.push_back(notoUi);
        c.legend.push_back(notoLegend);
    }
    c.reading = {readingReference(), notoUi};

    const scripts::CjkFace face = scripts::cjkFaceFor(languageCode, cps);
    c.cjk = static_cast<int>(face);
    if (face != scripts::CjkFace::None) {
        // The probe as well as the catalogue's own characters: a face chosen
        // for a half-finished catalogue must still be right for the whole.
        std::vector<unsigned int> need = cjk;
        for (const unsigned int cp : scripts::probeCodePoints(face)) { need.push_back(cp); }
        const std::vector<ChainFace> sys = cjkFacesFor(face, need);
        c.cjkFound = !sys.empty();
        for (const ChainFace& f : sys) {
            c.ui.push_back(f);
            c.legend.push_back(f);
            c.reading.push_back(f);
        }
    }
    return c;
}

namespace {

// Which CJK standard a language needs, remembered: the language list asks for
// every language on every frame it is open, and working it out walks the whole
// catalogue. Keyed by the catalogue's own identity as well as its code, so a
// translator's file that REPLACES a catalogue (FOXSDR_LANG_FILE) is judged
// afresh.
scripts::CjkFace faceOf(const std::string& code) {
    static std::map<std::string, std::pair<const void*, scripts::CjkFace>> cache;
    const void* id = cascade::i18n::findLanguage(code);
    if (const auto it = cache.find(code); it != cache.end() && it->second.first == id) {
        return it->second.second;
    }
    const scripts::CjkFace face = scripts::cjkFaceFor(code, cascade::i18n::codePoints(code));
    cache[code] = {id, face};
    return face;
}

}  // namespace

// The EXACT answer, which waits for a running scan: fonts.hpp states the one
// residual that follows (the language section's "Automatic (...)" and country
// keys, once, on its first frame, for about four bulk file reads).
bool canDraw(const std::string& languageCode) {
    const scripts::CjkFace face = faceOf(languageCode);
    return face == scripts::CjkFace::None || usableCjk(face, 0) != nullptr;
}

const char* unavailableReason(const std::string& languageCode) {
    if (canDraw(languageCode)) { return ""; }
    return scripts::missingFontReason(faceOf(languageCode), kWindows);
}

// The same answer as canDraw() wherever it is known, and never a wait: while the
// system-font scan has not decided this standard it starts the scan (once) and
// says Checking. The language list asks this for every row of every frame.
Drawable canDrawNow(const std::string& languageCode) {
    const scripts::CjkFace face = faceOf(languageCode);
    if (face == scripts::CjkFace::None) { return Drawable::Yes; }
    publishScan();
    if (const auto it = gScans.find(static_cast<int>(face)); it != gScans.end() && it->second.started) {
        return it->second.found.empty() ? Drawable::No : Drawable::Yes;
    }
    // A finished scan that still has no answer for this standard (it could not
    // get a thread): the on-demand walk, which is what canDraw() is.
    if (scanDone()) { return usableCjk(face, 0) != nullptr ? Drawable::Yes : Drawable::No; }
    startSystemFontScan();
    return Drawable::Checking;
}

void waitForSystemFontScan() {
    {
        std::unique_lock<std::mutex> lock(gScanMutex);
        gScanCv.wait(lock, [] { return gScanState != ScanState::Running; });
    }
    publishScan();
}

void shutdown() {
    gScanCancel.store(true);
    if (gScanThread.joinable()) { gScanThread.join(); }
}

void setReadDelayForTests(unsigned ms) { gReadDelayMs.store(ms); }

std::map<std::string, int> fileReadCountsForTests() {
    const std::lock_guard<std::mutex> lock(gReadCountsMutex);
    return gReadCounts;
}

std::vector<unsigned char> readFileForTests(const std::string& path) {
    const Bytes b = readFile(path);
    return b != nullptr ? *b : std::vector<unsigned char>();
}

std::size_t keptBytesForTests() { return gKept.size(); }

void resetScanForTests() {
    shutdown();  // a worker still reading finishes its file and goes
    gScanCancel.store(false);
    {
        const std::lock_guard<std::mutex> lock(gScanMutex);
        gScanState = ScanState::NotStarted;
        gScanOutcome = ScanOutcome();
    }
    gScanPublished = false;
    gScans.clear();
    gKept.clear();
    for (auto it = gPinned.begin(); it != gPinned.end();) {
        const unsigned char* d = it->second->data();
        it = (d == gGeorgia.data || d == gGeorgiaBold.data) ? std::next(it) : gPinned.erase(it);
    }
    const std::lock_guard<std::mutex> lock(gReadCountsMutex);
    gReadCounts.clear();
}

void applyLanguage(const std::string& languageCode) {
    if (languageCode != gWantLanguage) {
        gWantLanguage = languageCode;
        gDirty = true;
    }
}

void setPreferredPair(const std::string& pair) {
    if (pair != gPreferPair) {
        gPreferPair = pair;
        gDirty = true;
    }
}

// The names' faces need to know which system faces exist, and that is the
// background scan's to find out (see the scan above). So this starts it and
// notes the request; it does NOT mark the atlas dirty: applyPending() adds the
// names the first time it runs after the scan is done.
void requestLanguageNames() {
    gWantNames = true;
    startSystemFontScan();
}

bool applyPending() {
    publishScan();
    const bool namesReady = gWantNames && !gNamesDone && scanDone();
    if ((!gDirty && !namesReady) || gUi == nullptr) { return false; }
    gDirty = false;
    const Chain c = planChain(gWantLanguage);
    bool changed = false;
    // EXTEND ONLY WHEN NOTHING AHEAD MOVES: the same pair, the atlas's chains
    // are where the plan's begin, and - when the plan adds a face - no names
    // face sits in the way (a Japanese chain appended BEHIND a YaHei added for
    // the list would draw its kanji in Chinese forms). Anything else rebuilds.
    const bool samePrefix = c.pair == gPair && startsWith(c.ui, gChainUi) &&
                            startsWith(c.legend, gChainLegend) &&
                            startsWith(c.reading, gChainReading);
    const auto ui = samePrefix ? tail(c.ui, gChainUi.size()) : std::vector<ChainFace>();
    const auto lg = samePrefix ? tail(c.legend, gChainLegend.size()) : std::vector<ChainFace>();
    const auto rd = samePrefix ? tail(c.reading, gChainReading.size()) : std::vector<ChainFace>();
    const bool grows = !ui.empty() || !lg.empty() || !rd.empty();
    if (!samePrefix || (grows && !gNamesUi.empty())) {
        changed = rebuild(c);  // which forgets the names faces; found again below
    } else if (grows) {
        extendChain(gUi, ui, uiReference(), "UI", gChainUi);
        extendChain(gLegend, lg, legendReference(), "Legend", gChainLegend);
        extendChain(gReading, rd, readingReference(), "Reading", gChainReading);
        changed = true;
    }
    if (gWantNames && !gNamesDone && gUi != nullptr && scanDone()) {
        gNamesDone = true;
        changed = addNamesFaces() || changed;
        // THE FOOTPRINT AFTER OPENING THE LIST IS WHAT IT ALWAYS WAS. The scan
        // kept the bytes of the first usable face of every standard; the names
        // pass has just pinned the ones it needed, and pin() takes a file out of
        // gKept. What is left is files only LOOKED AT (JhengHei and Yu Gothic on a
        // desktop where YaHei already draws their names: 35 MB), and nothing
        // needs them now, so they go. A language chosen later whose file was let
        // go - Japanese, say - reads it once more, in one bulk read, on the GUI
        // thread, when it is put in a chain: that is the price of not holding 35 MB
        // for everyone for a choice most never make.
        gKept.clear();
    }
    return changed;
}

const std::string& pairInUse() { return gPair; }

std::vector<std::string> uiChainLabels() {
    // Read back from the ATLAS, in the order ImGui will ask the sources for a
    // glyph - not from this file's own lists, which say what was meant rather
    // than what is there.
    std::vector<std::string> out;
    if (gUi == nullptr) { return out; }
    for (const ImFontConfig* src : gUi->Sources) {
        const std::string name = src->Name;
        const std::size_t colon = name.find(": ");
        const std::string label = colon == std::string::npos ? name : name.substr(colon + 2);
        const bool names = name.rfind("UI names:", 0) == 0;
        out.push_back(names ? label + " (names)" : label);
    }
    return out;
}

bool load() {
    // GEORGIA FIRST, SAIRA IF IT IS NOT THERE (0.84.0), and taken as a pair: a
    // Georgia body with a Saira Condensed legend, or the reverse, would be two
    // typefaces that were never designed to sit together, so if either file
    // is missing both roles fall back to the embedded pair. planChain("en")
    // makes exactly that choice, English having no letter either pair lacks.
    gSystemSerif = haveGeorgia();
    gWantLanguage = "en";
    gWantNames = false;
    gNamesDone = false;
    gDirty = false;
    const bool ok = rebuild(planChain("en"));
    // From here on the language rules ask this file whether a catalogue can be
    // drawn, so neither "auto" nor a saved choice lands on one that cannot.
    cascade::i18n::setDrawablePredicate(&canDraw);
    return ok;
}

// --- Raw bytes, for callers that are not ImGui -------------------------------
//
// These exist so the remote interface can serve the SAME faces to a browser;
// see gui/font_blobs.hpp. They are defined here because this is already the one
// translation unit that includes font_assets.hpp, and the whole point of that
// restriction is not to compile three megabytes of initialiser twice.
//
// The first three return the upstream files unchanged, which is what the SIL
// Open Font License requires of a Reserved Font Name: redistribution yes,
// modification while keeping the name no. The two fallback faces are the
// subset tools/subset-noto.py cuts; Noto reserves no name.

